        timeout: const Duration(seconds: 60),
      );
      await harness.waitForOutput(settleMs: 400);
      final before = harness.viewportLines;
      expectComposerReserved(before, columns);

      // ── wave one's jobs settle under the camera (sleeps 21..25 s) ────
