  r'Background jobs \(5\) · 5 running · 0 done · '
  r'0 lost · older',
);

/// The first settle notice — `[bash] sh-… exited(0)` prints once per
/// settled job; the first of wave one's staggered exits.
const _firstSettle = 'exited(0)';

